import React, { useState, useEffect, useMemo } from 'react';
import { Helmet } from 'react-helmet';
import { useSelector, useDispatch } from 'react-redux';
import { fetchAllContent, refreshContent, toggleSaveOpportunityAsync, fetchSavedOpportunitiesAsync, toggleLikeOpportunityAsync, fetchLikedOpportunitiesAsync } from '../../store/contentSlice';
import Header from '../../components/ui/Header';
import Footer from '../../components/ui/Footer';
import Icon from '../../components/AppIcon';
import Button from '../../components/ui/Button';
import { useToast } from '../../contexts/ToastContext';
import FilterSidebar from './components/FilterSidebar';
import OpportunityCard from './components/OpportunityCard';
import CategoryCard from './components/CategoryCard';
import SavedSearchCard from './components/SavedSearchCard';
import ComparisonDrawer from './components/ComparisonDrawer';

const OpportunityDiscovery = () => {
  const dispatch = useDispatch();
  const { user, isAuthenticated } = useSelector((state) => state.auth);
  const { allOpportunities, savedOpportunities, likedOpportunities, isLoading } = useSelector((state) => state.content);
  const { addToast } = useToast();

  const [isFilterOpen, setIsFilterOpen] = useState(false);
  const [activeView, setActiveView] = useState('grid');
  const [sortBy, setSortBy] = useState('newest'); // Default to newest
  // Local state for saved removed, using Redux
  const [comparisonList, setComparisonList] = useState([]);
  const [isComparisonOpen, setIsComparisonOpen] = useState(false);
  const [showSavedSearches, setShowSavedSearches] = useState(false);



  const [filters, setFilters] = useState({
    search: '',
    category: 'all',
    location: 'all',
    deadline: 'all',
    verifiedOnly: false,
    // Future expansion
    eligibility: [],
    funding: [],
  });

  // Ensure data is loaded
  useEffect(() => {
    if (allOpportunities.length === 0) {
      dispatch(fetchAllContent());
    }
  }, [dispatch, allOpportunities.length]);

  // Fetch saved and liked opportunities if logged in
  useEffect(() => {
    if (isAuthenticated && user?.id) {
      dispatch(fetchSavedOpportunitiesAsync(user.id));
      dispatch(fetchLikedOpportunitiesAsync(user.id));
    }
  }, [dispatch, isAuthenticated, user?.id]);

  const categories = [
    { type: 'all', label: 'All', count: allOpportunities.length, trending: false },
    { type: 'scholarships', label: 'Scholarships', count: allOpportunities.filter(o => o.category?.toLowerCase().includes('scholarship')).length, trending: true },
    { type: 'internships', label: 'Internships', count: allOpportunities.filter(o => o.category?.toLowerCase().includes('internship')).length, trending: true },
    { type: 'jobs', label: 'Jobs', count: allOpportunities.filter(o => o.category?.toLowerCase().includes('job')).length, trending: false },
    { type: 'competitions', label: 'Competitions', count: allOpportunities.filter(o => o.category?.toLowerCase().includes('competition') || o.category?.toLowerCase().includes('contest')).length, trending: false },
    { type: 'fellowships', label: 'Fellowships', count: allOpportunities.filter(o => o.category?.toLowerCase().includes('fellowship')).length, trending: false }
  ];

  const savedSearches = [
    {
      id: 1,
      name: "Remote Tech Internships",
      description: "Software engineering and data science internships with remote work options",
      filters: ["Remote", "Internships", "Tech", "Paid"],
      alertEnabled: true
    },
    // ... we can keep these or fetch from DB later
  ];

  // Filtering Logic
  const filteredOpportunities = useMemo(() => {
    return allOpportunities.filter(opp => {
      // 1. Search (Title, Organization, Category)
      if (filters.search) {
        const searchLower = filters.search.toLowerCase();
        const matchesTitle = opp.title.toLowerCase().includes(searchLower);
        const matchesOrg = opp.organization.toLowerCase().includes(searchLower);
        const matchesCat = opp.category.toLowerCase().includes(searchLower);
        if (!matchesTitle && !matchesOrg && !matchesCat) return false;
      }

      // 2. Category
      if (filters.category !== 'all') {
        const oppCat = (opp.category || '').toLowerCase();
        const filterCat = filters.category.toLowerCase();
        // Check for exact match or pluralized match (removing 's' from filter/opp to compare)
        if (oppCat !== filterCat &&
          !oppCat.includes(filterCat.replace(/s$/, '')) &&
          !filterCat.includes(oppCat.replace(/s$/, ''))) {
          return false;
        }
      }

      // 3. Location (Improved matching)
      if (filters.location !== 'all') {
        const loc = (opp.location || '').toLowerCase();
        const filterLoc = filters.location.toLowerCase();

        // Map codes to words for better matching
        const locationMaps = {
          'usa': 'united states',
          'uk': 'united kingdom',
          'remote': 'remote'
        };

        const mappedValue = locationMaps[filterLoc] || filterLoc;
        if (!loc.includes(mappedValue) && !loc.includes(filterLoc)) return false;
      }

      // 4. Verified
      if (filters.verifiedOnly && !opp.verified) {
        return false;
      }

      // 5. Deadline Filter
      if (filters.deadline !== 'all') {
        if (filters.deadline === 'week' && (opp.daysLeft === null || opp.daysLeft > 7 || opp.daysLeft <= 0)) return false;
        if (filters.deadline === 'month' && (opp.daysLeft === null || opp.daysLeft > 30 || opp.daysLeft <= 0)) return false;
        if (filters.deadline === 'quarter' && (opp.daysLeft === null || opp.daysLeft > 90 || opp.daysLeft <= 0)) return false;
        if (filters.deadline === 'open' && opp.daysLeft !== null) return false; // Handled as Rolling/Open
      }

      // 6. Eligibility (Multi-select)
      if (filters.eligibility && filters.eligibility.length > 0) {
        const oppEligibility = (opp.eligibility || '').toLowerCase();
        const matchesAny = filters.eligibility.some(val => {
          // Map some common terms
          const map = {
            'undergraduate': 'undergrad',
            'graduate': 'grad',
            'recent_grad': 'recent graduate',
            'early_career': 'professional',
            'international': 'international'
          };
          const searchTerm = map[val] || val;
          return oppEligibility.includes(searchTerm) || oppEligibility.includes(val.replace('_', ' '));
        });
        if (!matchesAny) return false;
      }

      // 7. Funding (Multi-select)
      if (filters.funding && filters.funding.length > 0) {
        const oppStipend = (opp.stipend || '').toLowerCase();
        const oppFundingType = (opp.fundingType || '').toLowerCase();
        const fullText = `${oppStipend} ${oppFundingType}`;

        const matchesAny = filters.funding.some(val => {
          const map = {
            'fully_funded': 'full',
            'partially_funded': 'partial',
            'paid': 'paid',
            'stipend': 'stipend'
          };
          const searchTerm = map[val] || val;
          return fullText.includes(searchTerm) || fullText.includes(val.replace('_', ' '));
        });
        if (!matchesAny) return false;
      }

      return true;
    }).sort((a, b) => {
      if (sortBy === 'newest') return new Date(b.created_at) - new Date(a.created_at);
      if (sortBy === 'deadline') {
        // Put closing soon (smallest positive daysLeft) first, then long deadlines, then open
        const aDays = a.daysLeft <= 0 ? 9999 : a.daysLeft;
        const bDays = b.daysLeft <= 0 ? 9999 : b.daysLeft;
        return aDays - bDays;
      }
      if (sortBy === 'trending') return (b.trending === true) - (a.trending === true);
      return 0;
    });
  }, [allOpportunities, filters, sortBy]);

  const handleFilterChange = (key, value) => {
    setFilters(prev => ({ ...prev, [key]: value }));
  };

  const handleClearFilters = () => {
    setFilters({
      search: '',
      category: 'all',
      location: 'all',
      deadline: 'all',
      eligibility: [],
      funding: [],
      verifiedOnly: false
    });
  };

  const handleSaveOpportunity = async (id) => {
    if (!isAuthenticated) {
      addToast('Please sign in to save opportunities', 'info');
      return;
    }

    try {
      await dispatch(toggleSaveOpportunityAsync({ userId: user.id, opportunityId: id })).unwrap();
      const isSaved = savedOpportunities.some(o => o.id === id);
      addToast(isSaved ? 'Removed from saved' : 'Opportunity saved!', 'success');
      // Silent refresh to update counts/sync
      dispatch(refreshContent());
    } catch (error) {
      addToast('Failed to save opportunity', 'error');
    }
  };

  const handleLikeOpportunity = async (id) => {
    if (!isAuthenticated) {
      addToast('Please sign in to love opportunities', 'info');
      return;
    }

    try {
      await dispatch(toggleLikeOpportunityAsync({ userId: user.id, opportunityId: id })).unwrap();
      // Silent refresh to sync counts
      dispatch(refreshContent());
    } catch (error) {
      // Silent fail or toast
      console.error("Like failed", error);
    }
  };

  const handleShareOpportunity = (opportunity) => {
    if (navigator.share) {
      navigator.share({
        title: opportunity?.title,
        text: opportunity?.description,
        url: window.location?.href
      });
    } else {
      // Copy to clipboard fallback could be added
      alert('Share: ' + opportunity?.title);
    }
  };

  useEffect(() => {
    window.scrollTo(0, 0);
  }, []);

  return (
    <>
      <Helmet>
        <title>Discover Opportunities | LUC Hub</title>
        <meta name="description" content="Explore curated scholarships, internships, jobs, and competitions. Advanced filtering and personalized recommendations to find your perfect opportunity." />
      </Helmet>
      <div className="min-h-screen bg-background flex flex-col">
        <Header />

        <main className="flex-1">
          <div className="flex">
            {/* Filter Sidebar */}
            <FilterSidebar
              filters={filters}
              onFilterChange={handleFilterChange}
              onClearFilters={handleClearFilters}
              isOpen={isFilterOpen}
              onClose={() => setIsFilterOpen(false)}
            />

            {/* Main Content */}
            <div className="flex-1 min-w-0">
              {/* Hero Section */}
              <section className="bg-gradient-to-br from-primary/5 via-secondary/5 to-accent/5 py-8 md:py-12 px-4 lg:px-6">
                <div className="max-w-7xl mx-auto">
                  <div className="text-center mb-8">
                    <h1 className="text-3xl md:text-4xl lg:text-5xl font-bold text-primary mb-4">
                      Discover Your Next Opportunity
                    </h1>
                    <p className="text-base md:text-lg text-muted-foreground max-w-2xl mx-auto">
                      Explore {allOpportunities.length} curated opportunities across scholarships, internships, jobs, and more.
                      Filter by your preferences and save searches for instant alerts.
                    </p>
                  </div>

                  {/* Category Cards */}
                  <div className="flex gap-3 overflow-x-auto pb-4 scrollbar-hide justify-start md:justify-center">
                    {categories?.map((category) => (
                      <CategoryCard
                        key={category?.type}
                        category={category}
                        isActive={filters?.category === category?.type}
                        onClick={() => handleFilterChange('category', category?.type)}
                      />
                    ))}
                  </div>
                </div>
              </section>

              {/* Controls Bar */}
              <section className="sticky top-16 z-20 bg-card border-b border-border shadow-sm">
                <div className="max-w-7xl mx-auto px-4 lg:px-6 py-4">
                  <div className="flex items-center justify-between gap-4">
                    <div className="flex items-center gap-3">
                      <button
                        onClick={() => setIsFilterOpen(true)}
                        className="lg:hidden flex items-center gap-2 px-4 py-2 bg-primary text-primary-foreground rounded-lg hover:bg-primary/90 transition-colors"
                      >
                        <Icon name="SlidersHorizontal" size={18} />
                        <span className="text-sm font-medium">Filters</span>
                      </button>

                      <div className="hidden md:flex items-center gap-2 text-sm text-muted-foreground">
                        <Icon name="Search" size={16} />
                        <span>Showing {filteredOpportunities.length} opportunities</span>
                      </div>
                    </div>

                    <div className="flex items-center gap-2">
                      <select
                        value={sortBy}
                        onChange={(e) => setSortBy(e?.target?.value)}
                        className="px-3 py-2 bg-muted border border-border rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-primary"
                      >
                        <option value="newest">Newest First</option>
                        <option value="relevance">Most Relevant</option>
                        <option value="deadline">Be Closing Soon</option>
                        <option value="trending">Trending</option>
                      </select>

                      <div className="hidden md:flex items-center gap-1 bg-muted rounded-lg p-1">
                        <button
                          onClick={() => setActiveView('grid')}
                          className={`p-2 rounded transition-colors ${activeView === 'grid' ? 'bg-card shadow-sm' : 'hover:bg-card/50'}`}
                          aria-label="Grid view"
                        >
                          <Icon name="Grid3x3" size={18} />
                        </button>
                        <button
                          onClick={() => setActiveView('list')}
                          className={`p-2 rounded transition-colors ${activeView === 'list' ? 'bg-card shadow-sm' : 'hover:bg-card/50'}`}
                          aria-label="List view"
                        >
                          <Icon name="List" size={18} />
                        </button>
                      </div>
                    </div>
                  </div>
                </div>
              </section>

              {/* Opportunities Grid */}
              <section className="py-8 px-4 lg:px-6">
                <div className="max-w-7xl mx-auto">
                  {isLoading ? (
                    <div className="flex justify-center py-20">
                      <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
                    </div>
                  ) : filteredOpportunities.length > 0 ? (
                    <div className={activeView === 'grid' ? 'flex gap-6 overflow-x-auto pb-4 snap-x snap-mandatory scrollbar-hide pl-1 lg:pl-0 lg:grid lg:grid-cols-3 lg:gap-6 lg:overflow-visible lg:pb-0' : 'grid gap-6 grid-cols-1'}>
                      {filteredOpportunities.map((opportunity) => (
                        <div key={opportunity?.id} className="shrink-0 w-[85vw] sm:w-[60vw] snap-center lg:w-auto lg:shrink lg:snap-align-none">
                          <OpportunityCard
                            opportunity={opportunity}
                            onSave={handleSaveOpportunity}
                            onLike={handleLikeOpportunity}
                            onShare={handleShareOpportunity}
                            isSaved={savedOpportunities.some(saved => saved.id === opportunity.id)}
                            isLiked={likedOpportunities.includes(opportunity.id)}
                          />
                        </div>
                      ))}
                    </div>
                  ) : (
                    <div className="text-center py-20">
                      <Icon name="SearchX" size={48} className="mx-auto text-muted-foreground mb-4" />
                      <h3 className="text-xl font-bold mb-2">No opportunities found</h3>
                      <p className="text-muted-foreground">Try adjusting your filters or search criteria.</p>
                      <Button variant="link" onClick={handleClearFilters} className="mt-2">Clear all filters</Button>
                    </div>
                  )}

                  {/* Load More (only if needed/pagination implemented) */}
                  {filteredOpportunities.length > 12 && (
                    <div className="flex justify-center mt-12">
                      <Button variant="outline" size="lg" iconName="RefreshCw" iconPosition="left">
                        Load More Opportunities
                      </Button>
                    </div>
                  )}
                </div>
              </section>

              {/* CTA Section */}
              <section className="bg-gradient-to-br from-[#0f172a] via-[#1e293b] to-[#0891b2] py-12 md:py-16 px-4 lg:px-6">
                <div className="max-w-4xl mx-auto text-center">
                  <Icon name="Bell" size={48} color="#FFFFFF" className="mx-auto mb-6 opacity-80" />
                  <h2 className="text-2xl md:text-3xl lg:text-4xl font-bold text-white mb-4">
                    Never Miss an Opportunity
                  </h2>
                  <p className="text-base md:text-lg text-white/90 mb-8">
                    Save your search preferences and get instant alerts when new opportunities match your criteria.
                  </p>
                  <div className="flex flex-col sm:flex-row items-center justify-center gap-4">
                    <Button
                      variant="default"
                      size="xl"
                      iconName="Bell"
                      iconPosition="left"
                      className="bg-white text-[#0f172a] hover:bg-white/90 font-bold shadow-xl border-none"
                    >
                      Create Alert
                    </Button>
                  </div>
                </div>
              </section>
            </div>
          </div>
        </main>

        <Footer />
      </div>
    </>
  );
};

export default OpportunityDiscovery;